using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.Production;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Inventory;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Domain.Production;
using BARANG.Core.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace BARANG.Core.Infrastructure.Production;

#pragma warning disable CA1862,CA1725
public sealed class ProductionAdministration(CoreDbContext db,ITransactionExecutor tx,ICompanyContext company,Application.Abstractions.Actors.ICurrentActor current,IAuditWriter audit,TimeProvider time):IProductionAdministration
{
 private Guid Company=>company.RequireCompanyId(); private Guid Actor=>Guid.TryParse(current.Actor.UserId,out Guid id)?id:throw new InvalidOperationException("Actor required"); private DateTimeOffset Now=>time.GetUtcNow();
 public Task<Result<IReadOnlyList<ProductionJobView>>> GenerateAsync(GenerateProductionJobsCommand c,CancellationToken ct)=>tx.ExecuteAsync(t=>GenerateInsideTransactionAsync(c,t),ct);
 public async Task<Result<IReadOnlyList<ProductionJobView>>> GenerateInsideTransactionAsync(GenerateProductionJobsCommand c,CancellationToken ct){Order? order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==c.OrderId,ct);if(order is null)return Result.Failure<IReadOnlyList<ProductionJobView>>(ProductionErrors.NotFound);if(order.Status!=OrderStatus.Submitted)return Result.Failure<IReadOnlyList<ProductionJobView>>(ProductionErrors.OrderNotEligible);await db.Database.ExecuteSqlInterpolatedAsync($"select id from barang.orders where company_id={Company} and id={c.OrderId} for update",ct);List<ProductionJob> made=[];foreach(OrderItem item in await db.OrderItems.Where(x=>x.OrderId==order.Id&&x.IsActive).OrderBy(x=>x.Id).ToListAsync(ct)){Result first=await Add(item,null,ProductionJobType.DesignPreparation,null,null,made,ct);if(first.IsFailure)return Result.Failure<IReadOnlyList<ProductionJobView>>(first.Error);foreach(OrderPrintOperation op in await db.OrderPrintOperations.Where(x=>x.OrderItemId==item.Id&&x.IsActive).OrderBy(x=>x.Sequence).ToListAsync(ct)){Result print=await Add(item,op.Id,ProductionJobType.Print,op.ArtworkVersionId,op.FileVersionId,made,ct);if(print.IsFailure)return Result.Failure<IReadOnlyList<ProductionJobView>>(print.Error);}Result press=await Add(item,null,ProductionJobType.HeatPress,null,null,made,ct);if(press.IsFailure)return Result.Failure<IReadOnlyList<ProductionJobView>>(press.Error);}return Result.Success<IReadOnlyList<ProductionJobView>>(made.Select(View).ToArray());}
 private async Task<Result> Add(OrderItem item,Guid? operation,ProductionJobType type,Guid? artwork,Guid? file,List<ProductionJob> result,CancellationToken ct){string key=ProductionText.Key(item.Id,type,operation);ProductionJob? existing=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.GenerationKey==key,ct);if(existing is not null){result.Add(existing);return Result.Success();}Result<ProductionJob> made=ProductionJob.Create(Company,item.OrderId,item.Id,operation,type,artwork,file,Now);if(made.IsFailure)return Result.Failure(made.Error);db.Add(made.Value);History(made.Value,"Created",null);Log("production.job.created",made.Value.Id);result.Add(made.Value);return Result.Success();}
 public async Task<Result> ValidateWorkflowCompletionAsync(Guid orderId,ProductionJobType type,CancellationToken ct){List<OrderItem> items=await db.OrderItems.Where(x=>x.OrderId==orderId&&x.IsActive).OrderBy(x=>x.Id).ToListAsync(ct);if(items.Count==0)return Result.Failure(ProductionErrors.Incomplete);List<ProductionJob> jobs=await db.ProductionJobs.Where(x=>x.OrderId==orderId&&x.JobType==type&&x.Status==ProductionJobStatus.Completed).ToListAsync(ct);foreach(OrderItem item in items){List<ProductionJob> itemJobs=jobs.Where(x=>x.OrderItemId==item.Id).ToList();if(type==ProductionJobType.Print){List<OrderPrintOperation> ops=await db.OrderPrintOperations.Where(x=>x.OrderItemId==item.Id&&x.IsActive).ToListAsync(ct);foreach(OrderPrintOperation op in ops){ProductionJob? j=itemJobs.SingleOrDefault(x=>x.PrintOperationId==op.Id);if(j is null||j.QuantityCompleted is null||j.QuantityCompleted<item.Quantity||j.ArtworkVersionId!=op.ArtworkVersionId||j.FileVersionId!=op.FileVersionId)return Result.Failure(ProductionErrors.SourceMismatch);}}else if(itemJobs.SingleOrDefault(x=>x.PrintOperationId is null) is not{QuantityCompleted:{ } quantity}||quantity<item.Quantity)return Result.Failure(ProductionErrors.Incomplete);}return Result.Success();}
 public Task<Result<ProductionJobView>> GetAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,t);return j is null?Result.Failure<ProductionJobView>(ProductionErrors.NotFound):Result.Success(View(j));},ct);
 public Task<Result<ProductionPage>> QueueAsync(ProductionQueueQuery q,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(q.Page<1||q.PageSize is<1 or>100)return Result.Failure<ProductionPage>(ProductionErrors.Invalid);IQueryable<ProductionJob>x=db.ProductionJobs.AsNoTracking();if(q.Status is not null)x=x.Where(j=>j.Status==q.Status);if(q.JobType is not null)x=x.Where(j=>j.JobType==q.JobType);if(q.OperatorUserId is not null)x=x.Where(j=>j.AssignedOperatorUserId==q.OperatorUserId);if(q.EquipmentId is not null)x=x.Where(j=>j.AssignedEquipmentId==q.EquipmentId);if(q.Priority is not null)x=x.Where(j=>j.Priority==q.Priority);if(q.PlannedDate is not null){DateTimeOffset from=new(q.PlannedDate.Value.ToDateTime(TimeOnly.MinValue),TimeSpan.Zero);x=x.Where(j=>j.PlannedStartUtc>=from&&j.PlannedStartUtc<from.AddDays(1));}if(q.BranchId is not null)x=from j in x join e in db.Equipment on j.AssignedEquipmentId equals e.Id where e.BranchId==q.BranchId select j;long total=await x.LongCountAsync(t);List<ProductionJob> rows=await x.OrderByDescending(j=>j.Priority).ThenBy(j=>j.QueuePosition).ThenBy(j=>j.PlannedStartUtc).ThenBy(j=>j.CreatedAtUtc).ThenBy(j=>j.Id).Skip((q.Page-1)*q.PageSize).Take(q.PageSize).ToListAsync(t);return Result.Success(new ProductionPage(rows.Select(View).ToArray(),q.Page,q.PageSize,total));},ct);
 public Task<Result<IReadOnlyList<EquipmentCapacityView>>> CapacityAsync(DateTimeOffset?from,DateTimeOffset?to,CancellationToken ct)=>tx.ExecuteAsync(async t=>{DateTimeOffset f=from??Now.Date,u=to??f.AddDays(7);if(u<=f)return Result.Failure<IReadOnlyList<EquipmentCapacityView>>(ProductionErrors.Invalid);var equipment=await db.Equipment.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.EquipmentCode).ToListAsync(t);var jobs=await db.ProductionJobs.AsNoTracking().Where(x=>x.AssignedEquipmentId!=null&&x.Status!=ProductionJobStatus.Completed&&x.Status!=ProductionJobStatus.Failed&&(x.PlannedStartUtc==null||x.PlannedStartUtc<u)&&(x.PlannedEndUtc==null||x.PlannedEndUtc>f)).ToListAsync(t);return Result.Success<IReadOnlyList<EquipmentCapacityView>>(equipment.Select(e=>{List<ProductionJob>j=jobs.Where(x=>x.AssignedEquipmentId==e.Id).ToList();return new EquipmentCapacityView(e.Id,e.EquipmentCode,e.Name,j.Count(x=>x.Status is ProductionJobStatus.Planned or ProductionJobStatus.Ready),j.Count(x=>x.Status==ProductionJobStatus.InProgress),j.FirstOrDefault(x=>x.Status==ProductionJobStatus.InProgress)?.Id,j.Count==0?null:j.Min(x=>x.PlannedStartUtc),j.Count==0?null:j.Max(x=>x.PlannedEndUtc));}).ToArray());},ct);
 public Task<Result<IReadOnlyList<ProductionHistoryView>>> HistoryAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.ProductionJobs.AnyAsync(x=>x.Id==id,t))return Result.Failure<IReadOnlyList<ProductionHistoryView>>(ProductionErrors.NotFound);return Result.Success<IReadOnlyList<ProductionHistoryView>>((await db.ProductionJobHistory.AsNoTracking().Where(x=>x.ProductionJobId==id).OrderBy(x=>x.OccurredAtUtc).ThenBy(x=>x.Id).ToListAsync(t)).Select(x=>new ProductionHistoryView(x.Id,x.EventType,x.ActorUserId,x.OccurredAtUtc,x.Summary)).ToArray());},ct);
 public Task<Result<ProductionJobView>> PlanAsync(Guid id,PlanProductionJobCommand c,CancellationToken ct)=>Mutate(id,"Planned",c.Version,(j,n)=>j.Plan(c.Priority,c.PlannedStartUtc,c.PlannedEndUtc,c.QueuePosition,c.Version,n),null,ct);
 public Task<Result<ProductionJobView>> AssignOperatorAsync(Guid id,AssignOperatorCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>!await ValidOperator(c.OperatorUserId,t)?Result.Failure<ProductionJobView>(ProductionErrors.InvalidOperator):await MutateCore(id,"OperatorAssigned",c.Version,(j,n)=>j.AssignOperator(c.OperatorUserId,c.Version,n),c.OperatorUserId.ToString(),t),ct);
 public Task<Result<ProductionJobView>> AssignEquipmentAsync(Guid id,AssignEquipmentCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.Id==id,t);if(j is null)return Result.Failure<ProductionJobView>(ProductionErrors.NotFound);if(c.EquipmentId is not null&&!await Compatible(j.JobType,c.EquipmentId.Value,t))return Result.Failure<ProductionJobView>(ProductionErrors.IncompatibleEquipment);Result r=j.AssignEquipment(c.EquipmentId,c.Version,Now);if(r.IsFailure)return Result.Failure<ProductionJobView>(r.Error);History(j,"EquipmentAssigned",c.EquipmentId?.ToString());Log("production.equipment.assigned",j.Id);return Result.Success(View(j));},ct);
 public Task<Result<ProductionJobView>> StartAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.Id==id,t);if(j is null)return Result.Failure<ProductionJobView>(ProductionErrors.NotFound);if(j.AssignedOperatorUserId is null||!await ValidOperator(j.AssignedOperatorUserId.Value,t))return Result.Failure<ProductionJobView>(ProductionErrors.InvalidOperator);if(j.JobType!=ProductionJobType.DesignPreparation&&(j.AssignedEquipmentId is not Guid equipment||!await Compatible(j.JobType,equipment,t)))return Result.Failure<ProductionJobView>(ProductionErrors.EquipmentUnavailable);if(!await HasWarehouseIssueAsync(j.OrderId,j.OrderItemId,t))return Result.Failure<ProductionJobView>(ProductionErrors.WarehouseIssueRequired);Result r=j.Start(version,Now);if(r.IsFailure)return Result.Failure<ProductionJobView>(r.Error);History(j,"Started",null);Log("production.job.started",j.Id);return Result.Success(View(j));},ct);
 public Task<Result<ProductionJobView>> CompleteAsync(Guid id,CompleteProductionJobCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.Id==id,t);if(j is null)return Result.Failure<ProductionJobView>(ProductionErrors.NotFound);OrderItem?item=await db.OrderItems.SingleOrDefaultAsync(x=>x.Id==j.OrderItemId&&x.OrderId==j.OrderId&&x.IsActive,t);if(item is null)return Result.Failure<ProductionJobView>(ProductionErrors.SourceMismatch);if(c.QuantityCompleted is null||c.QuantityCompleted<item.Quantity)return Result.Failure<ProductionJobView>(ProductionErrors.QuantityRequired);Result r=j.Complete(c.QuantityCompleted,c.Notes,c.Version,Now);if(r.IsFailure)return Result.Failure<ProductionJobView>(r.Error);History(j,"Completed",c.Notes);Log("production.job.completed",j.Id);return Result.Success(View(j));},ct);
 public Task<Result<ProductionJobView>> FailAsync(Guid id,ProductionReasonCommand c,CancellationToken ct)=>Mutate(id,"Failed",c.Version,(j,n)=>j.Fail(c.Reason,c.Version,n),c.Reason,ct);public Task<Result<ProductionJobView>> SuspendAsync(Guid id,ProductionReasonCommand c,CancellationToken ct)=>Mutate(id,"Suspended",c.Version,(j,n)=>j.Suspend(c.Reason,c.Version,n),c.Reason,ct);
 public Task<Result<ProductionJobView>> ResumeAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.Id==id,t);if(j is null)return Result.Failure<ProductionJobView>(ProductionErrors.NotFound);if(j.AssignedOperatorUserId is null||!await ValidOperator(j.AssignedOperatorUserId.Value,t))return Result.Failure<ProductionJobView>(ProductionErrors.InvalidOperator);if(j.JobType!=ProductionJobType.DesignPreparation&&(j.AssignedEquipmentId is not Guid equipment||!await Compatible(j.JobType,equipment,t)))return Result.Failure<ProductionJobView>(ProductionErrors.EquipmentUnavailable);if(!await HasWarehouseIssueAsync(j.OrderId,j.OrderItemId,t))return Result.Failure<ProductionJobView>(ProductionErrors.WarehouseIssueRequired);Result r=j.Resume(version,Now);if(r.IsFailure)return Result.Failure<ProductionJobView>(r.Error);History(j,"Resumed",null);Log("production.job.resumed",j.Id);return Result.Success(View(j));},ct);
 private Task<Result<ProductionJobView>> Mutate(Guid id,string evt,long version,Func<ProductionJob,DateTimeOffset,Result> change,string?summary,CancellationToken ct)=>tx.ExecuteAsync(t=>MutateCore(id,evt,version,change,summary,t),ct);private async Task<Result<ProductionJobView>> MutateCore(Guid id,string evt,long version,Func<ProductionJob,DateTimeOffset,Result> change,string?summary,CancellationToken ct){ProductionJob?j=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.Id==id,ct);if(j is null)return Result.Failure<ProductionJobView>(ProductionErrors.NotFound);Result r=change(j,Now);if(r.IsFailure)return Result.Failure<ProductionJobView>(r.Error);History(j,evt,summary);Log($"production.job.{evt.ToLowerInvariant()}",j.Id);return Result.Success(View(j));}
 private async Task<bool> HasWarehouseIssueAsync(Guid orderId,Guid itemId,CancellationToken ct){OrderItem?item=await db.OrderItems.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==itemId&&x.OrderId==orderId&&x.IsActive,ct);if(item is null)return false;string uom=await(from v in db.ProductVariants join p in db.Products on v.ProductId equals p.Id where v.Id==item.ProductVariantId select p.UnitOfMeasureCode).SingleOrDefaultAsync(ct)??"";List<Guid> ids=await db.StockReservations.Where(x=>x.OrderItemId==itemId&&x.ProductVariantId==item.ProductVariantId).Select(x=>x.Id).ToListAsync(ct);decimal issued=await db.StockTransactions.Where(x=>x.TransactionType==StockTransactionType.Issue&&x.SourceType=="WAREHOUSE_ISSUE"&&x.SourceId!=null&&ids.Contains(x.SourceId.Value)&&x.ProductVariantId==item.ProductVariantId&&x.UomCode==uom).SumAsync(x=>(decimal?)Math.Abs(x.QuantityDelta),ct)??0;return issued>=item.Quantity;}
 private async Task<bool> ValidOperator(Guid user,CancellationToken ct)=>await db.ApplicationUsers.AnyAsync(x=>x.Id==user&&x.AccountState==Domain.Security.UserAccountState.Active,ct)&&await db.UserCompanies.AnyAsync(x=>x.UserId==user&&x.ValidFromUtc<=Now&&(x.ValidToUtc==null||x.ValidToUtc>Now),ct)&&await(from ur in db.UserRoles join rp in db.RolePermissions on ur.RoleId equals rp.RoleId join p in db.Permissions on rp.PermissionId equals p.Id where ur.UserId==user&&ur.ValidFromUtc<=Now&&(ur.ValidToUtc==null||ur.ValidToUtc>Now)&&p.Code=="production.execute" select ur.Id).AnyAsync(ct);
 private async Task<bool> Compatible(ProductionJobType type,Guid equipment,CancellationToken ct){Domain.Catalog.Equipment?e=await db.Equipment.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==equipment&&x.IsActive,ct);if(e is null||e.OperationalStatusCode is not("AVAILABLE" or "READY"))return false;string code=e.EquipmentTypeCode;return type switch{ProductionJobType.DesignPreparation=>false,ProductionJobType.Print=>code.Contains("PRINT",StringComparison.OrdinalIgnoreCase),ProductionJobType.HeatPress=>code.Contains("HEAT",StringComparison.OrdinalIgnoreCase)||code.Contains("PRESS",StringComparison.OrdinalIgnoreCase),_=>false};}
 private void History(ProductionJob j,string type,string?summary)=>db.ProductionJobHistory.Add(ProductionJobHistory.Create(Company,j.Id,type,Actor,Now,summary));private void Log(string action,Guid id)=>audit.Write(new(action,"production_job",id.ToString(),ChangeKind:AuditChangeKind.Modified));private static ProductionJobView View(ProductionJob j)=>new(j.Id,j.OrderId,j.OrderItemId,j.PrintOperationId,j.ReproductionRequestId,j.SourceProductionJobId,j.RootProductionJobId,j.ReproductionDepth,j.JobType,j.Status,j.Priority,j.QueuePosition,j.AssignedOperatorUserId,j.AssignedEquipmentId,j.PlannedStartUtc,j.PlannedEndUtc,j.StartedAtUtc,j.CompletedAtUtc,j.FailureReason,j.SuspensionReason,j.ArtworkVersionId,j.FileVersionId,j.QuantityCompleted,j.ExecutionNotes,j.Version);
}
